'use strict';
const wreckCurrentPosition=[-27.16304,153.36826];
const conditionState={tides:null,wind:null,marine:null,layers:{},time:null,view:'assessment',errors:[],request:0};
const conditionURLs={wind:'https://api.open-meteo.com/v1/forecast?latitude=-27.16304&longitude=153.36826&hourly=wind_speed_10m,wind_direction_10m,wind_gusts_10m,weather_code&wind_speed_unit=kn&timezone=Australia%2FBrisbane&forecast_days=3',marine:'https://marine-api.open-meteo.com/v1/marine?latitude=-27.16304&longitude=153.36826&hourly=wave_height,wave_direction,wave_period,ocean_current_velocity,ocean_current_direction&timezone=Australia%2FBrisbane&forecast_days=3&cell_selection=sea'};
const finiteValue=x=>typeof x==='number'&&Number.isFinite(x);
const displayValue=(n,unit)=>finiteValue(n)?n.toFixed(2)+' '+unit:'Unavailable';
const aest=t=>new Date(t).toLocaleString('en-AU',{timeZone:'Australia/Brisbane',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hour12:false});
function tideAt(t){const d=conditionState.tides;if(!d)return null;const i=Math.round((t-Date.parse(d.start))/600000);if(i<3||i>=d.values.length-3)return null;const values=d.values;return {height:values[i],rate:values[i+3]-values[i-3],range:Math.max(...values.slice(Math.max(0,i-72),i+73))-Math.min(...values.slice(Math.max(0,i-72),i+73))};}
function forecastAt(type,t){const d=conditionState[type];if(!d||Date.now()-Date.parse(d.retrievedAt)>6*3600000)return null;const h=d.hourly;const index=h.time.findIndex(s=>Math.abs(Date.parse(s+':00+10:00')-t)<1800000);return index<0?null:Object.fromEntries(Object.entries(h).map(([k,v])=>[k,v[index]]));}
function conditionValues(t){const w=forecastAt('wind',t),m=forecastAt('marine',t),tide=tideAt(t);return {wind:w?.wind_speed_10m,gust:w?.wind_gusts_10m,windDirection:w?.wind_direction_10m,code:w?.weather_code,wave:m?.wave_height,period:m?.wave_period,current:finiteValue(m?.ocean_current_velocity)?m.ocean_current_velocity/1.852:null,currentDirection:m?.ocean_current_direction,tideRate:tide?.rate,height:tide?.height,range:tide?.range};}
function conditionMetrics(v){return `<div class="condition-metrics"><div><small>Tide · jetty prediction</small><b>${displayValue(v.height,'m LAT')}</b><span>${finiteValue(v.tideRate)?(v.tideRate>=0?'Rising':'Falling')+' '+Math.abs(v.tideRate).toFixed(2)+' m/h':'Rate unavailable'}</span></div><div><small>Wind · forecast</small><b>${displayValue(v.wind,'kn')}</b><span>Gust ${displayValue(v.gust,'kn')} · from ${displayValue(v.windDirection,'°')}</span></div><div><small>Waves · regional model</small><b>${displayValue(v.wave,'m')}</b><span>Period ${displayValue(v.period,'s')}</span></div><div><small>Current · regional model</small><b>${displayValue(v.current,'kn')}</b><span>Flow towards ${displayValue(v.currentDirection,'°')}</span></div></div>`;}
function assessmentHTML(v){const a=assessWrecks(v);return `<div class="current-state"><strong>${a.title}</strong><span>${a.flags.length?a.flags.join(' · '):'Local channel conditions still need checking.'}</span>${a.missing.length?'<span>Missing: '+a.missing.join(', ')+'</span>':''}</div><p class="assessment-limit">Unvalidated screening rules; not a swim clearance. Regional currents do not resolve the beach–wreck gap.</p>${conditionMetrics(v)}`;}
function showCurrentHazard(view='assessment'){
 conditionState.view=view;$('#featurePanel').hidden=false;$('#featureTitle').textContent=view==='assessment'?'Wrecks · conditions':({tide:'Tangalooma Jetty · tides',wind:'Wind forecast · model cell',marine:'Waves & current · model cell'}[view]||'Wrecks · conditions');
 const t=conditionState.time||Date.now(),v=conditionValues(t);
 const src=conditionState[view==='tide'?'tides':view];
 $('#featureAttributes').innerHTML=`<div id="assessmentReadout">${assessmentHTML(v)}</div><p><b>${aest(t)} AEST</b> · change time in the Layers panel</p>${view!=='assessment'&&src?.latitude?'<p>Model sample: '+formatUTM(src.latitude,src.longitude)+'</p>':''}<h4>Next 12 hours</h4><div class="condition-hours">${Array.from({length:12},(_,i)=>{const x=t+i*3600000,a=assessWrecks(conditionValues(x));return '<button data-condition-time="'+x+'" title="'+esc(a.title+': '+a.flags.join(', '))+'"><span>'+new Date(x).toLocaleTimeString('en-AU',{timeZone:'Australia/Brisbane',hour:'2-digit',hour12:false})+'</span><i style="background:'+a.color+'"></i><small>'+ (a.missing.length?'?':a.flags.length)+'</small></button>';}).join('')}</div><p class="fish-date">Numbers = triggered indicators; ? = incomplete. Grey is not a safe rating.</p><details class="condition-details"><summary>Data & method</summary><p>Conservative screening thresholds selected for this app, not locally validated swimmer limits: wind 15 kn, gust 20 kn, wave 1 m, regional current 1 kn, absolute tide change 0.30 m/h; any thunderstorm code. One trigger raises the flag. Missing inputs keep the result incomplete even when other triggers are present.</p><p>Tide rate is water-level change over one hour, not current speed; no slack-water time is inferred. The nearest hourly forecast is used within 30 minutes. Forecast downloads older than six hours are excluded.</p><p>Tide station: Tangalooma Jetty, roughly 1.3km south of the wrecks. Ten-minute 2026 predictions, metres LAT. Wind and marine markers show the returned model-cell locations. Current resolution is about 8km; waves about 5km. These cannot resolve the wreck channel or a swimmer’s drift.</p><p>Forecast retrieval: wind ${conditionState.wind?aest(Date.parse(conditionState.wind.retrievedAt)):'unavailable'}; marine ${conditionState.marine?aest(Date.parse(conditionState.marine.retrievedAt)):'unavailable'} AEST. Retrieval time is not model issue time. ${conditionState.errors.join(' ')}</p><a href="https://www.data.qld.gov.au/dataset/tangalooma-tide-gauge-predicted-interval-data" target="_blank" rel="noopener">MSQ/BOM tide predictions · CC BY 4.0</a><br><a href="https://open-meteo.com/en/docs/marine-weather-api" target="_blank" rel="noopener">Open-Meteo marine models · CC BY 4.0</a><br><a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener">Open-Meteo weather models</a><br><a href="https://www.tangalooma.com/resort-info/general-resort-information/swim-safety" target="_blank" rel="noopener">Local strong-current warning</a><p>Check local advice before entering. Do not swim against a strong running current.</p></details>`;
 $$('[data-condition-time]').forEach(b=>b.onclick=()=>{conditionState.time=Number(b.dataset.conditionTime);updateConditions();showCurrentHazard(view)});
}
function updateConditions(){
 const t=conditionState.time||Date.now(),v=conditionValues(t),a=assessWrecks(v);
 $('#conditionTimeLabel').textContent=aest(t)+' AEST';$('#conditionSummary').innerHTML='<b>'+a.title+'</b><small>'+(a.flags.join(' · ')||'Local check still required')+'</small>';
 const slider=$('#conditionTime');slider.value=Math.round(t/3600000);
 const labels={assessment:a.title,tide:'Tide '+displayValue(v.height,'m LAT'),wind:'Wind '+displayValue(v.wind,'kn'),marine:'Current '+displayValue(v.current,'kn')+' · waves '+displayValue(v.wave,'m')};
 for(const [id,l]of Object.entries(conditionState.layers)){l.setTooltipContent(labels[id]);if(id==='assessment')l.setStyle({color:a.color,fillColor:a.color});}
 if($('#featurePanel').hidden===false&&$('#featureAttributes .condition-metrics'))showCurrentHazard(conditionState.view);
}
async function refreshConditions(){
 const run=++conditionState.request;$('#conditionRefresh').disabled=true;$('#conditionSummary').textContent='Fetching forecasts…';conditionState.errors=[];
 const results=await Promise.allSettled(['wind','marine'].map(async type=>{
  let d;try{const r=await fetch(conditionURLs[type],{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();d=await r.json();if(!d.hourly?.time?.length)throw Error();d.retrievedAt=new Date().toISOString();}
  catch{const r=await fetch('data/wrecks-'+type+'-fallback.json',{cache:'no-cache'});d=await r.json();conditionState.errors.push(type+': bundled fallback; expires after six hours.');}
  if(run===conditionState.request)conditionState[type]=d;
 }));
 if(run!==conditionState.request)return;
 results.forEach((r,i)=>{if(r.status==='rejected'){conditionState[['wind','marine'][i]]=null;conditionState.errors.push(['wind','marine'][i]+' unavailable.')}});
 for(const type of ['wind','marine']){const d=conditionState[type],layer=conditionState.layers[type];if(d&&finiteValue(d.latitude)&&finiteValue(d.longitude)){layer.setLatLng([d.latitude,d.longitude]);if($('#conditionLayer-'+type).checked)layer.addTo(map);}else map.removeLayer(layer);}
 $('#conditionRefresh').disabled=false;updateConditions();
}
function setupCurrents(){
 const group=document.createElement('details');group.className='layergroup';group.open=true;group.innerHTML=`<summary>Water conditions · time layers</summary>${[['assessment','Wrecks hazard assessment'],['tide','Tide station · prediction'],['wind','Wind · forecast cell'],['marine','Waves & current · regional cell']].map(([id,label])=>'<label><input type="checkbox" id="conditionLayer-'+id+'" checked><span class="legend-icon point" style="--layer-color:'+(id==='assessment'?'#ae5428':'#267b9d')+'">●</span><span>'+label+'</span></label>').join('')}<div class="condition-controls"><label for="conditionTime">Forecast time</label><input id="conditionTime" type="range" step="1"><output id="conditionTimeLabel"></output><div><button id="conditionNow">Now</button><button id="conditionRefresh">Refresh data</button></div><div id="conditionSummary" role="status">Loading tide predictions…</div><button id="inspectCurrents" class="current-open">View conditions</button></div>`;$('#layerOptions').prepend(group);
 const base=Math.floor(Date.now()/3600000);conditionState.time=base*3600000;const slider=$('#conditionTime');slider.min=base;slider.max=base+48;slider.value=base;slider.oninput=()=>{conditionState.time=Number(slider.value)*3600000;updateConditions()};$('#conditionNow').onclick=()=>{const n=Math.floor(Date.now()/3600000);slider.min=n;slider.max=n+48;conditionState.time=n*3600000;updateConditions()};$('#conditionRefresh').onclick=refreshConditions;
 for(const id of ['assessment','tide','wind','marine']){
  const pos=id==='tide'?[-27.1751,153.3687333333]:wreckCurrentPosition;
  const l=L.circleMarker(pos,{radius:id==='assessment'?10:7,color:id==='assessment'?'#ae5428':'#267b9d',weight:2,fillOpacity:.85}).bindTooltip(id,{direction:'top',permanent:true,className:'condition-map-label'}).on('click',()=>{if(!measuring)showCurrentHazard(id)});conditionState.layers[id]=l;
  if(id==='assessment'||id==='tide')l.addTo(map);$('#conditionLayer-'+id).onchange=e=>{if(e.target.checked&&(id==='assessment'||id==='tide'||conditionState[id]))l.addTo(map);else map.removeLayer(l)};
 }
 $('#inspectCurrents').onclick=()=>{map.fitBounds(L.latLngBounds(Object.values(conditionState.layers).map(l=>l.getLatLng())),{padding:[55,55],maxZoom:13});showCurrentHazard()};
 fetch('data/tangalooma-tides-2026.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{conditionState.tides=d;updateConditions()}).catch(()=>{conditionState.errors.push('Tide predictions unavailable.');updateConditions()});
 refreshConditions();
 const card=document.createElement('article');card.className='card';card.innerHTML='<h2>Wrecks conditions</h2><p>Time-based tide, wind, wave and regional current indicators.</p><button id="conditionsCurrents">View on map</button>';$('#conditionsCards').prepend(card);$('#conditionsCurrents').onclick=()=>{tab('explore');sidebarMode('layers');map.fitBounds(L.latLngBounds(Object.values(conditionState.layers).map(l=>l.getLatLng())),{padding:[55,55],maxZoom:13});showCurrentHazard()};
}
